  // glue: GD_R is declared in c01_plume.js
  const GD_MAIR = 0.028964;
  function gdSolve(inp) {
    try {
      const d = Object.assign({}, gdDefaults, inp || {});
      const gas = GD_GASES[d.gas];
      if (!gas) throw new Error('Unknown gas: ' + d.gas);
      const Q = Number(d.Q_kg_s), u = Number(d.u10_m_s), H = Number(d.H_m), z = Number(d.z_m);
      const T = Number(d.T_K), p = Number(d.p_Pa), ppm = Number(d.Ctarget_ppm), stab = String(d.stab).toUpperCase();
      if (!(Q > 0)) throw new Error('Q_kg_s must be > 0');
      if (!(u >= 0.5 && u <= 20)) throw new Error('u10_m_s must be within [0.5, 20] m/s');
      if (!/^[A-F]$/.test(stab)) throw new Error('stab must be one of A-F');
      if (!(H >= 0)) throw new Error('H_m must be >= 0');
      if (!Number.isFinite(z)) throw new Error('z_m must be a finite number');
      if (!(T > 0)) throw new Error('T_K must be > 0');
      if (!(p > 0)) throw new Error('p_Pa must be > 0');
      if (!(ppm >= 0)) throw new Error('Ctarget_ppm must be >= 0');
      const useLFL = !(ppm > 0);
      const ct = useLFL ? gas.LFL : ppm * 1e-6;
      if (ct == null || !(ct > 0)) throw new Error('No target concentration: Ctarget_ppm is 0 and ' + gas.label + ' has no LFL');
      const rhoa = p * GD_MAIR / (GD_R * T);
      const rho0 = p * gas.M / (GD_R * T);
      const ckg = ct * p * gas.M / (GD_R * T);
      const warnings = [];
      const g = gdDistanceToConc(Q, u, H, stab, ckg, z, 1e4);
      const w = gdMaxWidth(Q, u, H, stab, ckg, z, g ? g.x : 1e4) || { yMax:null, xAt:null };
      let xHalf = null;
      if (useLFL) { const gh = gdDistanceToConc(Q, u, H, stab, ckg / 2, z, 1e4); xHalf = gh ? gh.x : null; }
      const bm = rho0 > rhoa ? gdBritterMcQuaid(Q / rho0, rho0, rhoa, u, ct) : null;
      const model = (bm && !bm.passive) ? 'Britter-McQuaid' : 'Gaussian (Pasquill-Gifford)';
      const xTarget = model === 'Britter-McQuaid' ? bm.x : (g ? g.x : null);
      if (xTarget != null && xTarget < 100) warnings.push('Briggs sigmas valid 100 m - 10 km: target distance below 100 m, result extrapolated');
      if (g && g.capped) warnings.push('Briggs sigmas valid 100 m - 10 km: Gaussian distance capped at 10 km');
      if (!g) warnings.push('Gaussian model: target concentration not reached on evaluated range');
      if (bm && Array.isArray(bm.warnings)) bm.warnings.forEach(m => warnings.push(m));
      if (rho0 < rhoa) warnings.push('H2/light gas: buoyant plume rise ignored');
      warnings.push('No averaging-time / peak-to-mean correction applied');
      const xmax = Math.max(10, (xTarget > 0 ? 3 * xTarget : 0) || 1000);
      const profile = [];
      for (let i = 0; i < 60; i++) {
        const x = Math.pow(xmax, i / 59);
        const c = gdPlumeConc(Q, u, H, stab, x, 0, z);
        profile.push({ x, c_vf: gdToVolFrac(c, gas.M, T, p) });
      }
      return {
        ok: true, warnings, model, ct, ckg, rho0, rhoa, xTarget,
        xGauss: g ? g.x : null, xHalf, yMax: w.yMax, xAtYmax: w.xAt, bm,
        densityCriterion: bm ? bm.densityCriterion : null, profile, norm: GD_NORM,
        breakdown: {
          gas: Object.assign({ key: d.gas, targetIsLFL: useLFL }, gas),
          sigmasAtTarget: xTarget > 0 ? gdSigmas(stab, xTarget) : null
        }
      };
    } catch (e) {
      return { ok: false, error: (e && e.message) ? e.message : String(e), warnings: [] };
    }
  }
