  function vceLogInterp(xs, ys, x) {
    var n = xs.length;
    if (!(x > xs[0])) return { y: ys[0], clamped: x < xs[0] || x !== x };
    if (!(x < xs[n - 1])) return { y: ys[n - 1], clamped: x > xs[n - 1] };
    var i = 0;
    while (i < n - 2 && x > xs[i + 1]) i++;
    var x0 = xs[i], x1 = xs[i + 1], y0 = ys[i], y1 = ys[i + 1];
    var t = (Math.log(x) - Math.log(x0)) / (Math.log(x1) - Math.log(x0));
    var y = (y0 > 0 && y1 > 0)
      ? Math.exp(Math.log(y0) + t * (Math.log(y1) - Math.log(y0)))
      : y0 + t * (y1 - y0);
    return { y: y, clamped: false };
  }

  function vceMECurve(table, strength, Rbar) {
    var s = Math.min(10, Math.max(1, strength));
    var sClamped = s !== strength;
    var lo = Math.floor(s), hi = Math.ceil(s);
    var a = vceLogInterp(VCE_RBAR, table[lo], Rbar);
    if (lo === hi) return { y: a.y, clamped: a.clamped || sClamped };
    var b = vceLogInterp(VCE_RBAR, table[hi], Rbar);
    var w = s - lo;
    var y = (a.y > 0 && b.y > 0)
      ? Math.exp((1 - w) * Math.log(a.y) + w * Math.log(b.y))
      : (1 - w) * a.y + w * b.y;
    return { y: y, clamped: a.clamped || b.clamped || sClamped };
  }

  function vceMEPoint(strength, E_J, R_m, p0_Pa, c0_m_s) {
    var ok = [strength, E_J, R_m, p0_Pa, c0_m_s].every(function (v) {
      return typeof v === 'number' && isFinite(v);
    }) && E_J > 0 && R_m > 0 && p0_Pa > 0 && c0_m_s > 0;
    if (!ok) return { Rbar: NaN, Ps_bar: NaN, dP_Pa: NaN, tbar: NaN,
      tpos_s: NaN, impulse_Pa_s: NaN, clamped: false };
    var L = Math.pow(E_J / p0_Pa, 1 / 3), Rbar = R_m / L;
    var p = vceMECurve(VCE_ME_P, strength, Rbar);
    var t = vceMECurve(VCE_ME_T, strength, Rbar);
    var dP = p.y * p0_Pa, tpos = t.y * L / c0_m_s;
    return { Rbar: Rbar, Ps_bar: p.y, dP_Pa: dP, tbar: t.y, tpos_s: tpos,
      impulse_Pa_s: 0.5 * dP * tpos, clamped: p.clamped || t.clamped };
  }

  function vceMEDistance(strength, E_J, p0_Pa, dP_Pa) {
    if (!(isFinite(strength) && E_J > 0 && p0_Pa > 0 && dP_Pa > 0 &&
          isFinite(E_J) && isFinite(p0_Pa) && isFinite(dP_Pa))) return null;
    var L = Math.pow(E_J / p0_Pa, 1 / 3), Ps = dP_Pa / p0_Pa;
    var r0 = VCE_RBAR[0], rN = VCE_RBAR[VCE_RBAR.length - 1];
    var f = function (r) { return vceMECurve(VCE_ME_P, strength, r).y; };
    if (Ps > f(r0)) return null;
    if (Ps < f(rN)) return { R_m: Infinity, Rbar: Infinity };
    if (f(rN) >= Ps) return { R_m: rN * L, Rbar: rN };
    var lo = Math.log(r0), hi = Math.log(rN);
    for (var k = 0; k < 80; k++) {
      var mid = 0.5 * (lo + hi);
      if (f(Math.exp(mid)) >= Ps) lo = mid; else hi = mid;
    }
    var Rbar = Math.exp(lo);
    return { R_m: Rbar * L, Rbar: Rbar };
  }

